begin;
select no_plan();
insert into auth.users(id,email) values('ac100000-0000-0000-0000-000000000001','owner@inbox.test'),('ac100000-0000-0000-0000-000000000002','desk@inbox.test'),('ac100000-0000-0000-0000-000000000003','hk@inbox.test');
insert into public.tenants(id,name,slug) values('ac200000-0000-0000-0000-000000000001','Inbox Business','inbox-business');
insert into public.properties(id,tenant_id,name,property_type) values('ac300000-0000-0000-0000-000000000001','ac200000-0000-0000-0000-000000000001','Inbox Hotel','hotel'),('ac300000-0000-0000-0000-000000000002','ac200000-0000-0000-0000-000000000001','Other Inbox','hotel');
insert into public.tenant_memberships(tenant_id,user_id,role) values('ac200000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000001','owner'),('ac200000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000002','member'),('ac200000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000003','member');
insert into public.property_memberships(tenant_id,property_id,user_id) values('ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000002'),('ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001','ac100000-0000-0000-0000-000000000003');
insert into public.user_roles(property_id,user_id,role_id) select 'ac300000-0000-0000-0000-000000000001',u,r.id from(values('ac100000-0000-0000-0000-000000000002'::uuid,'front_desk'),('ac100000-0000-0000-0000-000000000003'::uuid,'housekeeping'))v(u,k)join public.roles r on r.key=v.k and r.tenant_id is null;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ac100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.inbox_configure('ac300000-0000-0000-0000-000000000001','12345001','12345002','+9100001','vault:inbox-test','pending')$$,'42501',null,'manual IDs cannot bypass secure onboarding');
reset role;set local role service_role;
select public.inbox_configure('ac300000-0000-0000-0000-000000000001','12345001','12345002','+9100001','vault:inbox-test','pending');
reset role;set local role authenticated;
select is(public.inbox_workspace('ac300000-0000-0000-0000-000000000001')#>>'{connection,status}','pending','pending setup is not represented as enabled');
reset role;set local role service_role;
select public.inbox_configure('ac300000-0000-0000-0000-000000000001','12345001','12345002','+9100001','vault:inbox-test','active');
reset role;set local role authenticated;
reset role;
insert into public.conversations(id,tenant_id,property_id,connection_id,wa_contact_id,contact_name,last_inbound_at) select 'ac400000-0000-0000-0000-000000000001','ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001',id,'91000002','Alice Guest',now() from public.whatsapp_connections where property_id='ac300000-0000-0000-0000-000000000001';
insert into public.messages(id,tenant_id,property_id,conversation_id,direction,type,body,status,created_at) select format('ac600000-0000-0000-0000-%s',lpad(n::text,12,'0'))::uuid,'ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001','ac400000-0000-0000-0000-000000000001','in','text','Message '||n,'received',now() from generate_series(1,61)n;
insert into public.message_templates(id,tenant_id,property_id,name,body,status) values('ac500000-0000-0000-0000-000000000001','ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001','welcome','Welcome to the hotel.','approved'),('ac500000-0000-0000-0000-000000000002','ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001','variables','Hello {{1}}','approved');
set local role authenticated;
select is((public.inbox_workspace('ac300000-0000-0000-0000-000000000001','{"q":"ALICE"}')->>'total')::int,1,'search is case-insensitive');
select is((public.inbox_workspace('ac300000-0000-0000-0000-000000000002')->>'total')::int,0,'conversations stay scoped to the selected hotel');
select is(jsonb_array_length(public.inbox_workspace('ac300000-0000-0000-0000-000000000001')->'messages'),50,'latest page is bounded');
select is(public.inbox_workspace('ac300000-0000-0000-0000-000000000001')#>>'{messages,49,body}','Message 61','latest message is displayed instead of oldest 200');
select is(jsonb_array_length(public.inbox_workspace('ac300000-0000-0000-0000-000000000001','{"c":"ac400000-0000-0000-0000-000000000001","before":"ac600000-0000-0000-0000-000000000012"}')->'messages'),11,'older cursor reaches the remaining history');
select is((public.inbox_workspace('ac300000-0000-0000-0000-000000000001')#>>'{conversations,0,unread}')::int,61,'unread count is per user');
select public.inbox_mark_read('ac400000-0000-0000-0000-000000000001','ac600000-0000-0000-0000-000000000001');
select is((public.inbox_workspace('ac300000-0000-0000-0000-000000000001')#>>'{conversations,0,unread}')::int,60,'read marker respects stable message order when timestamps tie');
select public.inbox_mark_read('ac400000-0000-0000-0000-000000000001','ac600000-0000-0000-0000-000000000061');
select is((public.inbox_workspace('ac300000-0000-0000-0000-000000000001')#>>'{conversations,0,unread}')::int,0,'latest marker clears older unread messages');
select public.inbox_mark_read('ac400000-0000-0000-0000-000000000001','ac600000-0000-0000-0000-000000000001');
select is((public.inbox_workspace('ac300000-0000-0000-0000-000000000001')#>>'{conversations,0,unread}')::int,0,'older read marker cannot move unread watermark backwards');
select throws_ok($$select public.inbox_workspace('ac300000-0000-0000-0000-000000000001','{"c":"ac400000-0000-0000-0000-000000000001","before":"ac600000-0000-0000-0000-000000009999"}')$$,'22023',null,'invalid history cursor cannot leak or select another conversation');
select lives_ok($$select public.inbox_manage('ac400000-0000-0000-0000-000000000001',1,'claim')$$,'owner without explicit property membership can claim');
select is((select assigned_to from public.conversations where id='ac400000-0000-0000-0000-000000000001'),'ac100000-0000-0000-0000-000000000001'::uuid,'owner assignment is saved');
select throws_ok($$select public.inbox_manage('ac400000-0000-0000-0000-000000000001',1,'close')$$,'40001',null,'stale conversation action is rejected');
select throws_ok($$select public.inbox_manage('ac400000-0000-0000-0000-000000000001',2,'assign','ac100000-0000-0000-0000-000000000003')$$,'22023',null,'assignee must have inbox access');
select set_config('request.jwt.claims','{"sub":"ac100000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.inbox_manage('ac400000-0000-0000-0000-000000000001',2,'claim')$$,'22023',null,'claim cannot silently steal another teammate conversation');
select throws_ok($$select public.claim_conversation('ac400000-0000-0000-0000-000000000001')$$,'22023',null,'legacy claim cannot bypass assignment ownership');
select is((public.inbox_workspace('ac300000-0000-0000-0000-000000000001')#>>'{conversations,0,unread}')::int,61,'one teammate read marker does not mark another teammate read');
select set_config('request.jwt.claims','{"sub":"ac100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.inbox_manage('ac400000-0000-0000-0000-000000000001',2,'assign','ac100000-0000-0000-0000-000000000002');
select set_config('test.message',public.inbox_send('ac400000-0000-0000-0000-000000000001','ac700000-0000-0000-0000-000000000001','Hello guest')::text,true);
select is(public.inbox_send('ac400000-0000-0000-0000-000000000001','ac700000-0000-0000-0000-000000000001','Retry'),current_setting('test.message')::uuid,'reply retry is idempotent');
select is((select count(*)::int from public.messages where conversation_id='ac400000-0000-0000-0000-000000000001' and direction='out'),1,'one reply request queues one message');
select public.inbox_manage('ac400000-0000-0000-0000-000000000001',4,'close');
select throws_ok($$select public.inbox_send('ac400000-0000-0000-0000-000000000001','ac700000-0000-0000-0000-000000000002','Closed reply')$$,'22023',null,'closed conversation must be reopened before replying');
select throws_ok($$select public.send_whatsapp_message('ac400000-0000-0000-0000-000000000001','Legacy closed reply')$$,'22023',null,'legacy send cannot bypass closed-conversation rule');
select public.inbox_manage('ac400000-0000-0000-0000-000000000001',5,'reopen');
select throws_ok($$select public.inbox_send('ac400000-0000-0000-0000-000000000001','ac700000-0000-0000-0000-000000000003',null,'ac500000-0000-0000-0000-000000000002')$$,'22023',null,'unsupported template variables are blocked');
reset role;
update public.conversations set last_inbound_at=now()-interval '2 days' where id='ac400000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.inbox_send('ac400000-0000-0000-0000-000000000001','ac700000-0000-0000-0000-000000000004','Late reply')$$,'22023',null,'expired reply window blocks free text');
select set_config('test.template',public.inbox_send('ac400000-0000-0000-0000-000000000001','ac700000-0000-0000-0000-000000000005',null,'ac500000-0000-0000-0000-000000000001')::text,true);
reset role;
insert into public.consent_records(tenant_id,property_id,wa_contact_id,status,source)values('ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001','91000002','opted_out','test');
set local role authenticated;
select throws_ok($$select public.inbox_send('ac400000-0000-0000-0000-000000000001','ac700000-0000-0000-0000-000000000006',null,'ac500000-0000-0000-0000-000000000001')$$,'22023',null,'opted-out guest cannot receive a template');
reset role;set local role service_role;
select is((select count(*)::int from public.claim_outbound_messages_v2(10)),0,'worker does not claim messages after opt-out');
select is((select status from public.messages where id=current_setting('test.message')::uuid),'failed','queued reply is failed after consent changes');
reset role;
insert into public.consent_records(tenant_id,property_id,wa_contact_id,status,source)values('ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001','91000002','opted_in','test');
update public.conversations set last_inbound_at=now() where id='ac400000-0000-0000-0000-000000000001';
set local role authenticated;
select lives_ok($$select public.inbox_retry(current_setting('test.message')::uuid)$$,'known unsent failure can be retried after consent and window are restored');
reset role;set local role service_role;
select is((select count(*)::int from public.claim_outbound_messages_v2(10)),1,'worker claims eligible queued reply');
select is((select count(*)::int from public.claim_outbound_messages_v2(10)),0,'worker cannot double-claim a live lease');
select ok((public.validate_outbound_claim(current_setting('test.message')::uuid,1)->>'ok')::boolean,'claim is validated before sending');
select is(public.complete_outbound_message_v2(current_setting('test.message')::uuid,99,true,'mock-stale'),false,'stale attempt cannot acknowledge a message');
select ok(public.complete_outbound_message_v2(current_setting('test.message')::uuid,1,true,'mock-success'),'valid attempt can record provider acknowledgment');
select is((select status from public.messages where id=current_setting('test.message')::uuid),'sent','sent is distinct from queued');
reset role;set local role authenticated;
select public.inbox_retry(current_setting('test.template')::uuid);
reset role;set local role service_role;
select count(*) from public.claim_outbound_messages_v2(10);
reset role;
update public.messages set locked_at=now()-interval '10 minutes' where id=current_setting('test.template')::uuid;
set local role service_role;
select is((select count(*)::int from public.claim_outbound_messages_v2(10)),0,'abandoned HTTP lease is not automatically resent');
select ok((select delivery_uncertain from public.messages where id=current_setting('test.template')::uuid),'abandoned delivery is marked uncertain');
reset role;set local role authenticated;
select throws_ok($$select public.inbox_retry(current_setting('test.template')::uuid)$$,'22023',null,'uncertain delivery cannot be manually retried blindly');
reset role;set local role service_role;
select throws_ok($$select public.inbox_configure('ac300000-0000-0000-0000-000000000001','99999999','12345002','+9100001','vault:test','active')$$,'22023',null,'business number cannot be replaced underneath existing history');
reset role;set local role authenticated;
select ok(not has_function_privilege('authenticated','public.claim_outbound_messages_v2(integer)','execute'),'worker claim endpoint is not available to staff');
reset role;
insert into public.conversations(id,tenant_id,property_id,connection_id,wa_contact_id,contact_name)
select format('ac900000-0000-0000-0000-%s',lpad(n::text,12,'0'))::uuid,'ac200000-0000-0000-0000-000000000001','ac300000-0000-0000-0000-000000000001',c.id,'9200'||n,'Contact '||n from public.whatsapp_connections c cross join generate_series(1,26)n where c.property_id='ac300000-0000-0000-0000-000000000001';
set local role authenticated;
select is((public.inbox_workspace('ac300000-0000-0000-0000-000000000001')->>'total')::int,27,'conversation count is not limited to visible rows');
select is(jsonb_array_length(public.inbox_workspace('ac300000-0000-0000-0000-000000000001')->'conversations'),25,'first conversation page is bounded');
select is(jsonb_array_length(public.inbox_workspace('ac300000-0000-0000-0000-000000000001','{"page":2}')->'conversations'),2,'older conversations remain reachable on page two');
select set_config('request.jwt.claims','{"sub":"ac100000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.inbox_workspace('ac300000-0000-0000-0000-000000000001')$$,'42501',null,'staff without WhatsApp permission cannot read inbox');
select throws_ok($$select public.inbox_send('ac400000-0000-0000-0000-000000000001','ac700000-0000-0000-0000-000000000009','Forbidden')$$,'42501',null,'staff without WhatsApp permission cannot reply');
reset role;set local role anon;
select throws_ok($$select public.inbox_workspace('ac300000-0000-0000-0000-000000000001')$$,'42501',null,'anonymous caller cannot read guest messages');
select * from finish();
rollback;
